"""Real Monaco/theme persistence and audio player; explicit AI/audio transport fixtures."""
import argparse,json,shutil,sys,tempfile,threading,wave
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright,expect

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,required=True);parser.add_argument('--installed-from',type=Path,required=True);parser.add_argument('--audio',type=Path,required=True);parser.add_argument('--emma',type=Path,required=True);a=parser.parse_args();a.output.mkdir(parents=True,exist_ok=True);checks=[];errors=[];speech=[];requests=[]
 def passed(label):checks.append(label);print('PASS',label,flush=True)
 with tempfile.TemporaryDirectory(prefix='zenit-voice-theme-') as tmp:
  base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'main.py').write_text('# comentario\nvalue=41\nprint(value+1)\n');(ws/'other.py').write_text('# segundo\nprint(42)\n');dest=base/'profile/extensions';dest.mkdir(parents=True);index=json.loads((a.installed_from/'installed.json').read_text(encoding='utf-8-sig'));info=index['zhuangtongfa.material-theme'];shutil.copytree(a.installed_from/info['directory'],dest/info['directory']);(dest/'installed.json').write_text(json.dumps({'zhuangtongfa.material-theme':info}));app=Application(ROOT,ws,data_dir=base/'profile');app.workspace.trusted=True;app.features.studio.update({'onboarded':True});app.features.prefs.update({'general.showWelcome':False,'appearance.motion':False,'updates.automatic':False,'extensions.checkUpdatesOnOpen':False,'ai.voiceDirectory':str(a.emma)})
  # The player receives a WAV generated by the real selected Emma voice in the
  # separate integration check. Replaying it avoids loading the model again.
  with wave.open(str(a.audio)) as wav:expected_duration=wav.getnframes()/wav.getframerate()
  voice=app.features.voice
  def start(text):
   speech.append(text);ident='qa-audio-'+str(len(speech));voice.jobs[ident]={'id':ident,'done':True,'cancelled':False,'error':'','message':'Voz de Emma lista','audio':a.audio.read_bytes(),'cancel':threading.Event()};return {'id':ident}
  voice.start=start
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True);context=browser.new_context(viewport={'width':1672,'height':917});page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get editor(){return editor},get platform(){return platformUI},get studio(){return studio},openFile};')
    context.route('**/src/app.js',inject);url=f'http://127.0.0.1:{server.server_port}';page.goto(url);page.wait_for_function('window.lumen?.ready');page.evaluate('async()=>{await __qa.openFile("main.py");await __qa.openFile("other.py");__qa.editor.activate("main.py");const p=__qa.platform;await p.applyExtensionTheme(p.extensionThemes.findIndex(t=>t.label==="One Dark Pro Darker"));window.__model=__qa.editor.view.getModel();}')
    def theme():return page.evaluate('()=>({id:document.documentElement.dataset.extensionTheme,theme:__qa.editor.view._themeService.getColorTheme().themeName,label:document.querySelector("#theme-trigger").getAttribute("aria-label"),background:getComputedStyle(document.documentElement).getPropertyValue("--editor").trim()})')
    assert page.evaluate('document.querySelector("[data-ai-action=fix]").getBoundingClientRect().bottom<=document.querySelector(".assistant-scroll").getBoundingClientRect().bottom'),page.evaluate('JSON.stringify(Object.fromEntries(["[data-ai-action=fix]",".assistant-scroll",".assistant-hero",".melody-tools-row"].map(s=>[s,document.querySelector(s).getBoundingClientRect().toJSON()])))');passed('All four Melody actions fit the reference desktop height with the compact tool row')
    current=theme();assert current['id'].endswith('One Dark Pro Darker') and current['theme']=='lumen-extension-theme' and 'One Dark Pro Darker' in current['label'];passed('Toolbar shows the actual selected One Dark Pro variant')
    for operation in ('__qa.editor.split("other.py")','__qa.platform.savePreference("editor.fontSize",16)','__qa.platform.loadContributions()','__qa.platform.savePreference("editor.wordWrap",true)'):
     page.evaluate('async()=>await '+operation);assert theme()==current;assert page.evaluate('[...__qa.editor.models.values()].some(r=>r.model===__model)')
    passed('One Dark Pro survives real split, settings and contribution refresh without replacing the buffer');page.screenshot(path=str(a.output/'one-dark-stable.png'))
    # Observe at request dispatch, before the actual contribution response.
    startup=[]
    def contributions(route):
     startup.append(page.evaluate('()=>({id:document.documentElement.dataset.extensionTheme,background:getComputedStyle(document.documentElement).getPropertyValue("--editor").trim()})'));route.fulfill(response=route.fetch())
    page.route('**/api/platform/extensions/contributions',contributions);page.reload();page.wait_for_function('window.lumen?.ready');assert startup and all(s['id']==current['id'] and s['background']==current['background'] for s in startup),(startup,current,page.evaluate('localStorage.getItem("zenit.themeAppearance")')); assert theme()==current;passed('Reload restores the effective shell colours before extension contributions arrive');page.unroute('**/api/platform/extensions/contributions',contributions)
    updates=[]
    def settings(route):updates.append(route.request.post_data_json);route.fulfill(response=route.fetch())
    page.route('**/api/platform/settings',settings);page.evaluate('async()=>await __qa.platform.savePreference("appearance.theme","forest")');assert len(updates)==1 and updates[0]['settings']=={'appearance.theme':'forest','appearance.extensionTheme':''};assert page.evaluate('document.documentElement.dataset.theme==="forest"&&!document.documentElement.dataset.extensionTheme');passed('Switching to a native theme commits base and extension selection atomically');page.unroute('**/api/platform/settings',settings)
    page.evaluate('async()=>{await __qa.platform.applyExtensionTheme(__qa.platform.extensionThemes.findIndex(t=>t.label==="One Dark Pro Darker"));await __qa.openFile("main.py");__qa.platform.prefs["ai.provider"]="ollama";__qa.platform.prefs["ai.model"]="fixture";__qa.platform.host.confirmDialog=async()=>true;}')
    page.route('**/api/platform/ai/start',lambda route:(requests.append(route.request.post_data_json),route.fulfill(json={'id':'qa-answer'}))[-1]);page.route('**/api/platform/ai/job?*',lambda route:route.fulfill(json={'offset':1,'delta':'Hola, soy Melody. Vamos a revisar tu código y avanzar paso a paso.\n```python\nprint(42)\n```','done':True}));page.locator('#ai-input').fill('Explica este código');page.locator('#ai-form .send-button').click();expect(page.locator('.chat-message.assistant .melody-listen')).to_be_visible();assert len(speech)==0;passed('Completed answers offer Listen; speech never starts automatically')
    page.locator('.chat-message.assistant .melody-listen').click();page.wait_for_function('__qa.platform.voice.audio.duration>1');duration=page.evaluate('__qa.platform.voice.audio.duration');assert abs(duration-expected_duration)<.01 and len(speech)==1;passed('Authenticated WAV playback uses the real 24 kHz Emma sample');page.evaluate('__qa.platform.voice.audio.play()');page.wait_for_function('!__qa.platform.voice.audio.paused');page.locator('.voice-pause').click();assert page.evaluate('__qa.platform.voice.audio.paused');page.locator('.voice-pause').click();page.wait_for_function('!__qa.platform.voice.audio.paused');passed('Pause and Resume control the same audio without regenerating speech');page.screenshot(path=str(a.output/'melody-speaking.png'))
    unauth=page.evaluate('async()=>{const response=await fetch("/api/platform/ai/voice/audio?id=qa-audio-1",{credentials:"same-origin"});return response.status}');assert unauth==403;passed('Audio requires the session token, not merely a loopback URL');page.locator('.voice-stop').click();expect(page.locator('.melody-voice')).to_be_hidden();assert page.evaluate('__qa.platform.voice.audio.paused&&!__qa.platform.voice.audio.getAttribute("src")');passed('Stop removes the source and releases session audio')
    page.evaluate('()=>{__qa.editor.view.setSelection(new monaco.Selection(2,1,2,9))}');page.locator('.melody-selection-voice').click();page.wait_for_function('__qa.platform.voice.audio.duration>1');assert speech[-1]=='value=41';passed('The selection button sends only the actual selected text');page.evaluate('__qa.platform.clearAI()');expect(page.locator('.melody-voice')).to_be_hidden();passed('Clearing the conversation stops its voice player')
    page.evaluate('()=>{const p=__qa.platform,m=__qa.editor.view.getModel();p.companion.render({status:"ready",text:"Revisa la línea 2.",snapshot:{version:m.getVersionId(),position:{lineNumber:2,column:1}}});}')
    page.locator('.melody-companion-card .melody-listen').click();page.wait_for_function('__qa.platform.voice.audio.duration>1');assert speech[-1]=='Revisa la línea 2.'
    page.evaluate('()=>__qa.editor.view.getModel().setValue("# nueva revisión\\nvalue=42\\nprint(value)\\n")');expect(page.locator('.melody-companion-card .melody-listen')).to_be_hidden();expect(page.locator('.melody-voice')).to_be_hidden();assert page.evaluate('!__qa.platform.companion.spokenAdvice&&!__qa.platform.companion.advice');passed('Editing the real Monaco model expires its advice and stops the associated Emma audio')
    for width,height in ((1280,720),(1366,768),(1920,1080)):
     page.set_viewport_size({'width':width,'height':height});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(a.output/f'voice-layout-{width}.png'))
    passed('Speech controls fit three desktop sizes without global overflow');assert not errors,errors;passed('No uncaught JavaScript errors');browser.close()
  finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
 (a.output/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors,'theme':current,'audioDuration':duration,'audioFixture':'Replay of separately verified actual selected Emma generation; AI transport fixture, no external model evaluation.'},indent=2),encoding='utf-8')
if __name__=='__main__':main()
